create extension if not exists vector with schema extensions;
create type public.user_role as enum ('Super Admin','Meeting Secretary','Faculty / Officer','Member','Auditor');
create type public.meeting_status as enum ('Draft','Transcribed','Pending Approval','Published');
create type public.meeting_type as enum ('online','offline');
create type public.action_status as enum ('Pending','In Progress','Completed');
create type public.policy_status as enum ('Draft','Under Review','Approved','Archived');
create table public.users(id uuid primary key references auth.users(id) on delete cascade,email text not null unique,role public.user_role not null default 'Member',department text,created_at timestamptz not null default now());
create table public.meetings(id uuid primary key default gen_random_uuid(),title text not null,date timestamptz not null,location text,type public.meeting_type not null,status public.meeting_status not null default 'Draft',created_by uuid not null references public.users(id),assigned_approver_id uuid references public.users(id));
create table public.participants(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meetings(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,attendance_status text not null default 'Invited',unique(meeting_id,user_id));
create table public.minutes(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meetings(id) on delete cascade,raw_transcript text,summary text,version integer not null default 1,is_approved boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.decisions(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meetings(id) on delete cascade,minute_id uuid not null references public.minutes(id) on delete cascade,decision_text text not null,action_item text,assignee_id uuid references public.users(id),due_date date,status public.action_status not null default 'Pending');
create table public.events(id uuid primary key default gen_random_uuid(),title text not null,start_time timestamptz not null,end_time timestamptz not null,description text,location text);
create table public.policies(id uuid primary key default gen_random_uuid(),title text not null,content text not null,version integer not null default 1,status public.policy_status not null default 'Draft',effective_date date,updated_by uuid references public.users(id),updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references public.users(id),action text not null,target_table text not null,target_id uuid,changes jsonb,timestamp timestamptz not null default now());
create table public.embeddings(id uuid primary key default gen_random_uuid(),parent_type text not null check(parent_type in ('meeting','policy','event')),parent_id uuid not null,chunk_content text not null,embedding vector(1536) not null,metadata jsonb not null default '{}'::jsonb);
create index embeddings_vector_idx on public.embeddings using hnsw (embedding vector_cosine_ops); create index meetings_status_idx on public.meetings(status); create index meetings_date_idx on public.meetings(date); create index audit_timestamp_idx on public.audit_logs(timestamp desc);
alter table public.users enable row level security; alter table public.meetings enable row level security; alter table public.participants enable row level security; alter table public.minutes enable row level security; alter table public.decisions enable row level security; alter table public.events enable row level security; alter table public.policies enable row level security; alter table public.audit_logs enable row level security; alter table public.embeddings enable row level security;
create or replace function public.current_role() returns public.user_role language sql stable security definer set search_path=public as $$ select role from public.users where id=auth.uid() $$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer','Auditor') $$;
create policy users_self_or_admin on public.users for select using(id=auth.uid() or public.current_role()='Super Admin'); create policy users_admin_update on public.users for update using(public.current_role()='Super Admin') with check(public.current_role()='Super Admin');
create policy meetings_read on public.meetings for select using(status='Published' or created_by=auth.uid() or assigned_approver_id=auth.uid() or public.is_staff()); create policy meetings_secretary_insert on public.meetings for insert with check(public.current_role() in ('Super Admin','Meeting Secretary') and created_by=auth.uid()); create policy meetings_staff_update on public.meetings for update using(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer')) with check(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer'));
create policy participants_read on public.participants for select using(public.is_staff() or user_id=auth.uid()); create policy participants_staff_write on public.participants for all using(public.current_role() in ('Super Admin','Meeting Secretary')) with check(public.current_role() in ('Super Admin','Meeting Secretary'));
create policy minutes_read on public.minutes for select using(public.is_staff() or exists(select 1 from public.meetings m where m.id=meeting_id and m.status='Published')); create policy minutes_staff_write on public.minutes for all using(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer')) with check(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer'));
create policy decisions_read on public.decisions for select using(public.is_staff() or exists(select 1 from public.meetings m where m.id=meeting_id and m.status='Published')); create policy decisions_staff_write on public.decisions for all using(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer')) with check(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer'));
create policy events_read on public.events for select using(public.is_staff() or true); create policy events_staff_write on public.events for all using(public.current_role() in ('Super Admin','Meeting Secretary')) with check(public.current_role() in ('Super Admin','Meeting Secretary'));
create policy policies_read on public.policies for select using(status='Approved' or public.is_staff()); create policy policies_staff_write on public.policies for all using(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer')) with check(public.current_role() in ('Super Admin','Meeting Secretary','Faculty / Officer'));
create policy audit_read on public.audit_logs for select using(public.current_role() in ('Super Admin','Auditor')); create policy audit_insert on public.audit_logs for insert with check(auth.uid() is not null);
create policy embeddings_read on public.embeddings for select using(public.is_staff() or exists(select 1 from public.meetings m where m.id=parent_id and parent_type='meeting' and m.status='Published') or exists(select 1 from public.policies p where p.id=parent_id and parent_type='policy' and p.status='Approved')); create policy embeddings_staff_write on public.embeddings for all using(public.current_role() in ('Super Admin','Meeting Secretary')) with check(public.current_role() in ('Super Admin','Meeting Secretary'));
create or replace function public.hybrid_search(query_text text, query_embedding vector(1536), match_count integer default 10) returns table(parent_type text,parent_id uuid,chunk_content text,metadata jsonb,similarity double precision) language sql stable as $$ with semantic as (select e.parent_type,e.parent_id,e.chunk_content,e.metadata,1-(e.embedding<=>query_embedding) similarity from public.embeddings e order by e.embedding<=>query_embedding limit match_count*2), lexical as (select e.parent_type,e.parent_id,e.chunk_content,e.metadata,ts_rank(to_tsvector('english',e.chunk_content),websearch_to_tsquery('english',query_text)) similarity from public.embeddings e where to_tsvector('english',e.chunk_content) @@ websearch_to_tsquery('english',query_text) limit match_count*2) select parent_type,parent_id,chunk_content,metadata,similarity from (select * from semantic union all select * from lexical) x order by similarity desc limit match_count $$;
grant execute on function public.hybrid_search(text,vector,integer) to authenticated;
insert into storage.buckets(id,name,public) values('meeting-media','meeting-media',false) on conflict(id) do nothing;
